update countries set gdp='$216 Billion', population='3.0 Million', current_conditions_date='September 2026', updated_at=now(), geopolitical_alert_level='Severe', geopolitical_alert='LNG exports blocked by the Hormuz closure; Qatar was struck in earlier waves and is a lead mediator in Iran talks.', geopolitical_alert_date='2026-09-24', current_conditions_score=4.5, current_conditions_summary='The Strait of Hormuz has been effectively closed to commercial shipping since 28 Feb 2026 (single-digit daily transits vs ~85 pre-crisis); the US naval blockade of Iran was reinstated in mid-July after the interim ceasefire collapsed. US–Iran talks are under way — on 23 Sep Iran tabled a road map including a 60-day regionwide ceasefire and phased reopening, not yet agreed. Qatar''s LNG exports depend on Hormuz and remain largely halted; Qatar is also one of the main mediators with Iran.', current_conditions_factors='LNG exports halted · Prior strikes · Mediation role', current_conditions_outlook='Strong balance sheet, but operating conditions remain severely impaired until Hormuz reopens.' where name='Qatar';
