update countries set gdp='$552 Billion', population='12 Million', current_conditions_date='September 2026', updated_at=now(), geopolitical_alert_level='High', geopolitical_alert='Hormuz effectively closed since 28 Feb 2026; Jebel Ali and re-export trade heavily disrupted. US–Iran talks under way (Iran proposed a 60-day ceasefire on 23 Sep).', geopolitical_alert_date='2026-09-24', current_conditions_score=5.0, current_conditions_summary='The Strait of Hormuz has been effectively closed to commercial shipping since 28 Feb 2026 (single-digit daily transits vs ~85 pre-crisis); the US naval blockade of Iran was reinstated in mid-July after the interim ceasefire collapsed. US–Iran talks are under way — on 23 Sep Iran tabled a road map including a 60-day regionwide ceasefire and phased reopening, not yet agreed. The UAE was among the most frequently targeted states in earlier strike waves; Jebel Ali throughput and re-export flows remain heavily disrupted.', current_conditions_factors='Hormuz closure · Elevated strike exposure · Logistics rerouting · Talks under way', current_conditions_outlook='Structural fundamentals remain strong; near-term conditions depend on the outcome of US–Iran talks. Re-test timing and business-continuity plans before committing capital.' where name='United Arab Emirates';
